export const ANNOTATE_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"referrer\" content=\"no-referrer\">\n<title>Passage annotation</title>\n<style>\n:root {\n  --paper: #f7f3ea;\n  --paper-2: #efe8da;\n  --card: #fbf8f2;\n  --ink: #1f1b16;\n  --ink-2: #4a4238;\n  --muted: #8a7f70;\n  --rule: #d9cfbd;\n  --red: #b3322a;\n  --red-soft: #f3dcd6;\n  --mark: #f6e3a1;\n  --focus: #2f5d8a;\n  --ok: #2f6b3a;\n  --ok-soft: #dcebd9;\n  --serif: \"Iowan Old Style\", \"Palatino Linotype\", Palatino, \"Book Antiqua\", \"URW Palladio L\", Georgia, Cambria, serif;\n  --sans: system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --paper: #1b1915; --paper-2: #24211c; --card: #211e19; --ink: #ebe4d6; --ink-2: #c9bfae;\n    --muted: #8f8676; --rule: #3a352d; --red: #e0685c; --red-soft: #3d2420; --mark: #5a4a1c; --focus: #7fb0e0; --ok: #7cc28a; --ok-soft: #1f3322;\n  }\n}\n* { box-sizing: border-box; }\nhtml, body { margin: 0; background: var(--paper); color: var(--ink); }\nbody { font-family: var(--sans); font-size: 15px; line-height: 1.45; }\nheader { position: sticky; top: 0; z-index: 5; background: var(--paper); border-bottom: 1px solid var(--rule); padding: 8px 16px 6px; }\n.hrow { display: flex; align-items: center; gap: 12px; max-width: 1180px; margin: 0 auto; flex-wrap: wrap; }\n.brand { font-family: var(--serif); font-size: 17px; letter-spacing: .02em; white-space: nowrap; }\n.brand b { color: var(--red); font-weight: 600; }\n.tabs { display: flex; gap: 4px; }\n.tab { border: 1px solid var(--rule); background: var(--card); color: var(--ink-2); border-radius: 14px; padding: 2px 10px; font: inherit; font-size: 13px; cursor: pointer; white-space: nowrap; }\n.tab[aria-current=\"true\"] { background: var(--ink); color: var(--paper); border-color: var(--ink); }\n.tab.locked { opacity: .55; }\n.progress { flex: 1; display: flex; align-items: center; gap: 10px; min-width: 160px; }\n.bar { flex: 1; height: 6px; background: var(--paper-2); border-radius: 3px; overflow: hidden; border: 1px solid var(--rule); }\n.bar > i { display: block; height: 100%; width: 0; background: var(--red); transition: width .3s ease; }\n.count { font-variant-numeric: tabular-nums; color: var(--ink-2); font-size: 13px; text-align: right; white-space: nowrap; }\n.tools { display: flex; gap: 2px; }\n.tabs { overflow-x: auto; scrollbar-width: none; max-width: 100%; }\n.tabs::-webkit-scrollbar { display: none; }\nbutton.link, a.link { background: none; border: 0; color: var(--ink-2); cursor: pointer; font: inherit; font-size: 14px; padding: 4px 6px; border-radius: 4px; text-decoration: none; white-space: nowrap; }\nbutton.link:hover, a.link:hover { color: var(--ink); background: var(--paper-2); }\nmain { max-width: 1180px; margin: 0 auto; padding: 18px 16px 90px; display: grid; grid-template-columns: minmax(0, 1fr) 390px; gap: 32px; }\n\n/* ---- passage */\narticle { font-family: var(--serif); color: var(--ink); max-width: 40em; }\n.ctx { color: var(--muted); font-size: 16px; line-height: 1.6; }\n.ctx p { margin: 0 0 .7em; }\n.ctx.before { border-bottom: 1px dashed var(--rule); padding-bottom: .6em; margin-bottom: 1.1em; }\n.ctx.after { border-top: 1px dashed var(--rule); padding-top: .6em; margin-top: 1.1em; }\n.ctx-body { max-height: 6.5em; overflow: hidden; }\n.ctx.before .ctx-body { display: flex; flex-direction: column; justify-content: flex-end; }\n.ctx.open .ctx-body { max-height: none; display: block; }\n.ctx-toggle { background: none; border: 0; padding: 0 0 0 8px; color: var(--ink-2); font: inherit; font-size: 11px; text-decoration: underline; cursor: pointer; text-transform: none; letter-spacing: 0; }\n.ctx-label { font-family: var(--sans); font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); margin-bottom: .4em; }\n#text { font-size: 19px; line-height: 1.7; hyphens: auto; -webkit-hyphens: auto; text-align: left; }\n#text p { margin: 0 0 .85em; }\n#text p + p { text-indent: 1.4em; margin-top: -.5em; }\n#text::selection, #text *::selection { background: var(--red-soft); }\nmark { background: var(--mark); color: inherit; padding: 0 .05em; border-radius: 2px; }\n.passage-box { background: var(--card); border: 1px solid var(--rule); border-left: 3px solid var(--red); padding: 16px 20px 6px; border-radius: 2px; }\n.passage-label { font-family: var(--sans); font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: var(--red); margin-bottom: .5em; }\n.panel { font-family: var(--serif); font-size: 19px; padding: 36px 8px; color: var(--ink-2); max-width: 36em; }\n.panel h2 { font-weight: 600; color: var(--ink); margin: 0 0 10px; font-size: 26px; }\n.panel p { margin: 8px 0; }\n.panel .primary { font-family: var(--sans); font-size: 15px; margin-top: 12px; }\n\n/* ---- form */\naside { position: sticky; top: 64px; align-self: start; display: flex; flex-direction: column; gap: 14px; }\nfieldset { border: 0; margin: 0; padding: 0; }\nlegend, .flabel { font-size: 12px; font-weight: 600; color: var(--ink); margin-bottom: 6px; padding: 0; display: flex; justify-content: space-between; gap: 8px; width: 100%; }\nlegend .hint, .flabel .hint { font-weight: 400; color: var(--muted); white-space: nowrap; }\n.q { font-size: 13.5px; color: var(--ink-2); font-weight: 400; display: block; margin-top: 1px; }\n.seg { display: flex; gap: 6px; flex-wrap: wrap; }\n.seg .opt { flex: 1 1 0; justify-content: center; }\n.opt {\n  display: inline-flex; align-items: center; gap: 7px; cursor: pointer; user-select: none; -webkit-user-select: none;\n  border: 1px solid var(--rule); background: var(--card); color: var(--ink); border-radius: 5px;\n  padding: 7px 9px; min-height: 38px; font: inherit; font-size: 13.5px; text-align: left; touch-action: manipulation;\n}\n.opt:hover { border-color: var(--ink-2); }\n.opt[aria-pressed=\"true\"] { background: var(--ink); color: var(--paper); border-color: var(--ink); }\n.opt[aria-pressed=\"true\"] kbd { background: transparent; color: var(--paper); border-color: var(--paper); }\n.opt .sub { display: block; font-size: 11.5px; opacity: .75; }\n.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }\n.grid .opt { width: 100%; }\n.dim { opacity: .45; }\nkbd { font-family: var(--mono); font-size: 11px; border: 1px solid var(--rule); border-bottom-width: 2px; border-radius: 3px; padding: 0 4px; min-width: 1.5em; text-align: center; color: var(--ink-2); background: var(--paper); }\n.hidden { display: none !important; }\ntextarea { width: 100%; min-height: 48px; resize: vertical; font: inherit; font-size: 14px; color: var(--ink); background: var(--card); border: 1px solid var(--rule); border-radius: 4px; padding: 7px 9px; }\ntextarea:focus, .opt:focus-visible, button:focus-visible, a:focus-visible { outline: 2px solid var(--focus); outline-offset: 1px; }\ndetails summary { cursor: pointer; font-size: 12px; font-weight: 600; color: var(--ink-2); }\ndetails[open] summary { margin-bottom: 6px; }\n.ev-list { list-style: none; margin: 0 0 6px; padding: 0; display: flex; flex-direction: column; gap: 4px; }\n.ev-list li { font-family: var(--serif); font-size: 14px; background: var(--card); border: 1px solid var(--rule); border-radius: 4px; padding: 4px 28px 4px 8px; position: relative; }\n.ev-list li button { position: absolute; right: 4px; top: 2px; border: 0; background: none; color: var(--muted); cursor: pointer; font-size: 15px; }\n.ev-empty { color: var(--muted); font-size: 13px; }\n.actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }\n.primary { background: var(--red); color: #fff; border: 0; border-radius: 5px; padding: 9px 18px; min-height: 40px; font: inherit; font-weight: 600; cursor: pointer; }\n.primary:hover { filter: brightness(1.08); }\n.primary kbd { color: #fff; border-color: #fff8; background: transparent; }\n.secondary { background: none; border: 1px solid var(--rule); color: var(--ink-2); border-radius: 5px; padding: 8px 12px; min-height: 40px; font: inherit; cursor: pointer; }\n.small { font-size: 12.5px; padding: 4px 8px; min-height: 0; }\n#msg { min-height: 1.3em; font-size: 13px; color: var(--red); }\n#msg.ok { color: var(--ok); }\n\n/* ---- practice feedback */\n#feedback { display: flex; flex-direction: column; gap: 12px; }\n#feedback h3 { margin: 0; font-family: var(--serif); font-size: 20px; font-weight: 600; }\n.cmp { width: 100%; border-collapse: collapse; font-size: 13.5px; }\n.cmp th, .cmp td { text-align: left; padding: 6px 6px; border-bottom: 1px solid var(--rule); vertical-align: top; }\n.cmp th { font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); font-weight: 600; }\n.cmp td.same { background: var(--ok-soft); }\n.cmp td.diff { background: var(--red-soft); }\n.verdict { font-size: 11.5px; font-weight: 600; white-space: nowrap; }\n.verdict.same { color: var(--ok); } .verdict.diff { color: var(--red); }\n.rationale { font-family: var(--serif); font-size: 16px; line-height: 1.55; background: var(--card); border: 1px solid var(--rule); border-radius: 4px; padding: 10px 12px; }\n.miss { border-top: 1px solid var(--rule); padding-top: 12px; margin-top: 14px; font-size: 15px; }\n.miss .ex { font-size: 15.5px; line-height: 1.55; color: var(--ink); }\n.miss .cmp { margin: 8px 0; font-family: var(--sans); }\n.miss .cmp th { width: 7em; }\n.rationale b { font-family: var(--sans); font-size: 11px; text-transform: uppercase; letter-spacing: .07em; color: var(--red); display: block; margin-bottom: 4px; }\n\n/* ---- overlays */\n.overlay { position: fixed; inset: 0; background: rgba(20, 16, 12, .5); display: flex; align-items: flex-start; justify-content: center; padding: 6vh 12px; z-index: 20; }\n.sheet { background: var(--card); color: var(--ink); max-width: 760px; width: 100%; max-height: 86vh; overflow: auto; border-radius: 8px; padding: 20px 22px; border: 1px solid var(--rule); box-shadow: 0 10px 40px rgba(0, 0, 0, .25); }\n.sheet h2 { font-family: var(--serif); font-weight: 600; margin: 0 0 8px; font-size: 22px; }\n.sheet h3 { font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: var(--red); margin: 16px 0 6px; }\n.sheet dl { display: grid; grid-template-columns: max-content 1fr; gap: 4px 14px; margin: 0; font-size: 14px; }\n.sheet dt { font-family: var(--mono); font-size: 12px; color: var(--ink-2); padding-top: 2px; }\n.sheet dd { margin: 0; }\n.sheet p { margin: 6px 0; font-size: 15px; }\n.sheet .actions { margin-top: 14px; }\n\n/* ---- narrow screens: passage first, then the form; sticky submit bar */\n@media (max-width: 900px) {\n  main { grid-template-columns: 1fr; gap: 20px; padding-bottom: 110px; }\n  aside { position: static; }\n  article { max-width: none; }\n}\n@media (max-width: 640px) {\n  header { padding: 6px 10px 4px; }\n  .hrow { gap: 6px 8px; }\n  .brand { font-size: 15px; }\n  .progress { order: 5; flex-basis: 100%; }\n  header { position: static; }\n  .tabs { order: 4; flex-basis: 100%; }\n  .tab { font-size: 12.5px; padding: 3px 9px; }\n  .tools { margin-left: auto; }\n  button.link, a.link { font-size: 13px; padding: 4px 5px; }\n  main { padding: 12px 12px 110px; }\n  #text { font-size: 18px; }\n  .passage-box { padding: 12px 14px 4px; }\n  .ctx { font-size: 15px; }\n  kbd { display: none; }\n  .opt { min-height: 44px; font-size: 14.5px; }\n  .actions.main { position: fixed; left: 0; right: 0; bottom: 0; background: var(--paper); border-top: 1px solid var(--rule); padding: 8px 12px calc(8px + env(safe-area-inset-bottom)); z-index: 6; }\n  .actions.main .primary { flex: 1; }\n}\n</style>\n</head>\n<body>\n<header>\n  <div class=\"hrow\">\n    <div class=\"brand\">What <b>Stands</b> in the Way</div>\n    <nav class=\"tabs\" id=\"tabs\" aria-label=\"sets\"></nav>\n    <div class=\"progress\" aria-label=\"progress\">\n      <div class=\"bar\"><i id=\"bar\"></i></div>\n      <div class=\"count\" id=\"count\">&nbsp;</div>\n    </div>\n    <div class=\"tools\">\n      <a class=\"link\" id=\"guideLink\" href=\"/annotate/guide\" target=\"_blank\" rel=\"noopener noreferrer\" title=\"Open the guide (g)\"><span class=\"lbl\">Guide</span> <kbd>g</kbd></a>\n      <button class=\"link\" id=\"breakBtn\" title=\"Save &amp; take a break (b)\"><span class=\"lbl\">Break</span> <kbd>b</kbd></button>\n      <button class=\"link\" id=\"helpBtn\" title=\"Help (?)\"><span class=\"lbl\">Help</span> <kbd>?</kbd></button>\n    </div>\n  </div>\n</header>\n\n<main id=\"main\">\n  <section>\n    <div class=\"panel hidden\" id=\"panel\"></div>\n    <article id=\"article\">\n      <div class=\"ctx before\" id=\"ctxBeforeWrap\"><div class=\"ctx-label\">Before (for context only)<button type=\"button\" class=\"ctx-toggle\" data-for=\"ctxBeforeWrap\">show all</button></div><div class=\"ctx-body\" id=\"ctxBefore\"></div></div>\n      <div class=\"passage-box\"><div class=\"passage-label\" id=\"plabel\">Judge this passage</div><div id=\"text\">Loading&hellip;</div></div>\n      <div class=\"ctx after\" id=\"ctxAfterWrap\"><div class=\"ctx-label\">After (for context only)<button type=\"button\" class=\"ctx-toggle\" data-for=\"ctxAfterWrap\">show all</button></div><div class=\"ctx-body\" id=\"ctxAfter\"></div></div>\n    </article>\n  </section>\n\n  <aside id=\"side\">\n    <div id=\"form\">\n      <fieldset>\n        <legend><span>1. Is there a plot obstacle?<span class=\"q\">A character wants something, something is in the way, and it matters for what happens next.</span></span><span class=\"hint\">y / n / c</span></legend>\n        <div class=\"seg\" id=\"hasObstacle\"></div>\n      </fieldset>\n\n      <fieldset id=\"domainSet\" style=\"margin-top:14px\">\n        <legend><span>2. What kind of thing is in the way?<span class=\"q\">Pick the one that, if removed, would let the character go ahead.</span></span><span class=\"hint\">1&ndash;9, o</span></legend>\n        <div class=\"grid\" id=\"domains\"></div>\n      </fieldset>\n\n      <fieldset id=\"fcSet\" class=\"hidden\" style=\"margin-top:14px\">\n        <legend><span>2b. Why does the communication fail?</span><span class=\"hint\">Shift+1&ndash;6</span></legend>\n        <div class=\"grid\" id=\"fcs\"></div>\n      </fieldset>\n\n      <fieldset id=\"locusSet\" style=\"margin-top:14px\">\n        <legend><span>3. Where does the resistance come from?</span><span class=\"hint\">m / s / i</span></legend>\n        <div class=\"seg\" id=\"loci\"></div>\n      </fieldset>\n\n      <details id=\"extras\" style=\"margin-top:14px\">\n        <summary>Optional: evidence and note</summary>\n        <div class=\"flabel\">Evidence <span class=\"hint\">select words in the passage, then e</span></div>\n        <ul class=\"ev-list\" id=\"evList\"></ul>\n        <button type=\"button\" class=\"secondary small\" id=\"evBtn\">Add selected text</button>\n        <div class=\"flabel\" style=\"margin-top:10px\">Note <span class=\"hint\">t to type, Esc to leave</span></div>\n        <textarea id=\"note\" maxlength=\"4000\" placeholder=\"Anything odd about this passage?\"></textarea>\n      </details>\n\n      <div class=\"actions main\" style=\"margin-top:14px\">\n        <button class=\"primary\" id=\"submitBtn\">Submit <kbd>Enter</kbd></button>\n        <button class=\"secondary\" id=\"undoBtn\">Undo last <kbd>u</kbd></button>\n      </div>\n      <div id=\"msg\" role=\"status\" aria-live=\"polite\"></div>\n    </div>\n\n    <div id=\"feedback\" class=\"hidden\" aria-live=\"polite\">\n      <h3>Practice: how did you do?</h3>\n      <table class=\"cmp\"><thead><tr><th></th><th>You</th><th>Reference</th></tr></thead><tbody id=\"cmpBody\"></tbody></table>\n      <div class=\"rationale\"><b>Why</b><span id=\"rationale\"></span></div>\n      <div class=\"actions main\"><button class=\"primary\" id=\"nextBtn\">Next passage <kbd>Enter</kbd></button></div>\n    </div>\n  </aside>\n</main>\n\n<div id=\"help\" class=\"overlay hidden\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"helpTitle\">\n  <div class=\"sheet\">\n    <h2 id=\"helpTitle\">Quick reference</h2>\n    <p><b>Plot obstacle</b> = a character <b>wants</b> something + something is <b>in the way</b> + it <b>matters</b> for what happens next. Scenery, a passing mention, or a general complaint is not enough. Judge only the bordered passage; the grey text around it is context. <b>When unsure, choose &ldquo;Can&rsquo;t tell&rdquo;.</b> The full <a href=\"/annotate/guide\" target=\"_blank\" rel=\"noopener noreferrer\">guide</a> has examples.</p>\n    <h3>What kind of thing is in the way?</h3>\n    <dl id=\"helpDomains\"></dl>\n    <h3>Where does the resistance come from?</h3>\n    <dl id=\"helpLoci\"></dl>\n    <h3>Why does the communication fail?</h3>\n    <dl id=\"helpFcs\"></dl>\n    <h3>Keys</h3>\n    <dl>\n      <dt>y / n / c</dt><dd>Obstacle: yes / no / can&rsquo;t tell.</dd>\n      <dt>1&ndash;9, o</dt><dd>The kind of obstacle (choosing one also sets &ldquo;yes&rdquo;).</dd>\n      <dt>Shift+1&ndash;6</dt><dd>Why communication fails (only for Communication).</dd>\n      <dt>m / s / i</dt><dd>Where it comes from: material, social, inner.</dd>\n      <dt>e</dt><dd>Add the selected words as evidence (optional).</dd>\n      <dt>t</dt><dd>Write a note (Esc to leave the note field).</dd>\n      <dt>Enter</dt><dd>Submit, or go on after practice feedback. Ctrl+Enter inside the note.</dd>\n      <dt>u</dt><dd>Undo your last submission in this set and reopen it (not for practice).</dd>\n      <dt>q</dt><dd>Switch to the next set (practice / main / teaching).</dd>\n      <dt>b</dt><dd>Save &amp; take a break. Everything you submitted is already saved.</dd>\n      <dt>g</dt><dd>Open the guide in a new tab.</dd>\n      <dt>? / h</dt><dd>Show or hide this help. Esc closes it.</dd>\n    </dl>\n  </div>\n</div>\n\n<div id=\"pause\" class=\"overlay hidden\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pauseTitle\">\n  <div class=\"sheet\" style=\"max-width:520px\">\n    <h2 id=\"pauseTitle\">Taking a break</h2>\n    <p>Everything you submitted is saved on the server. The passage you were working on is kept in this browser, and the timer is paused.</p>\n    <p>You can close this tab. To come back, open <b>the same personal link</b> again (bookmark it), on any device.</p>\n    <p id=\"pauseStats\" style=\"color:var(--muted)\"></p>\n    <div class=\"actions\"><button class=\"primary\" id=\"resumeBtn\">Resume <kbd>Enter</kbd></button></div>\n  </div>\n</div>\n\n<div id=\"welcome\" class=\"overlay hidden\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"welcomeTitle\">\n  <div class=\"sheet\" style=\"max-width:600px\">\n    <h2 id=\"welcomeTitle\">Welcome, and thank you</h2>\n    <div id=\"welcomeBody\"></div>\n    <div class=\"actions\"><a class=\"secondary\" href=\"/annotate/guide\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"text-decoration:none\">Read the guide</a><button class=\"primary\" id=\"startBtn\">Start <kbd>Enter</kbd></button></div>\n  </div>\n</div>\n\n<script>\n(function () {\n  \"use strict\";\n  var BASE = location.pathname.replace(/\\/+$/, \"\");\n  var SECONDS_PER_ITEM = 30;\n\n  var HAS = [\n    { v: \"yes\", label: \"Yes\", key: \"y\" },\n    { v: \"no\", label: \"No\", key: \"n\" },\n    { v: \"insufficient_context\", label: \"Can’t tell\", key: \"c\" }\n  ];\n  var DOMAINS = [\n    { v: \"DISTANCE_TRAVEL\", label: \"Distance / travel\", key: \"1\", locus: \"material_external\", def: \"Being far away, a slow or hard journey, a missed coach or train, a road that can't be used.\" },\n    { v: \"COMMUNICATION_INFORMATION\", label: \"Communication / information\", key: \"2\", locus: null, def: \"A message that fails, is late, lost, hidden or misread; a secret; not knowing a key fact; mistaken identity.\" },\n    { v: \"DARKNESS_VISIBILITY\", label: \"Darkness / can't see\", key: \"3\", locus: \"material_external\", def: \"Night, fog, no light, hiding in the dark: not being able to see or be seen.\" },\n    { v: \"ILLNESS_BODY_DEATH\", label: \"Illness / body / death\", key: \"4\", locus: \"material_external\", def: \"Sickness, injury, weakness, pregnancy, dying or a death.\" },\n    { v: \"MONEY_PROPERTY_LAW\", label: \"Money / property / law\", key: \"5\", locus: \"social_institutional\", def: \"Poverty, debt, wills and inheritance, contracts, courts, police.\" },\n    { v: \"SOCIAL_RANK_CONVENTION\", label: \"Social rank / rules\", key: \"6\", locus: \"social_institutional\", def: \"Class, manners, reputation, marriage rules, what a woman or a servant 'may not' do, a parent's authority as a rule.\" },\n    { v: \"INTERPERSONAL_CONFLICT\", label: \"A person opposing\", key: \"7\", locus: \"social_institutional\", def: \"A specific person actively blocks, tricks, threatens or fights the character.\" },\n    { v: \"INNER_STATE\", label: \"Inner state (own mind)\", key: \"8\", locus: \"internal_psychological\", def: \"The character's own fear, doubt, pride, guilt, shyness or indecision.\" },\n    { v: \"NATURE_WEATHER\", label: \"Nature / weather\", key: \"9\", locus: \"material_external\", def: \"Storms, floods, snow, the sea, wild land, animals.\" },\n    { v: \"OTHER\", label: \"Other\", key: \"o\", locus: null, def: \"A real obstacle that fits none of these (add a short note).\" }\n  ];\n  var LOCI = [\n    { v: \"material_external\", label: \"Material\", sub: \"things, bodies, places\", key: \"m\", def: \"The physical world: distance, darkness, weather, illness, objects, machines.\" },\n    { v: \"social_institutional\", label: \"Social\", sub: \"people, rules, money\", key: \"s\", def: \"Other people and society: someone opposing, rules, class, law, money, deliberate deception.\" },\n    { v: \"internal_psychological\", label: \"Inner\", sub: \"the character's own mind\", key: \"i\", def: \"The character's own mind: fear, doubt, pride, guilt, indecision.\" }\n  ];\n  var FCS = [\n    { v: \"infrastructure\", label: \"No way to send it / too slow\", key: \"1\", locus: \"material_external\", def: \"Slow post, no telegraph, too far, the post hasn't come.\" },\n    { v: \"accidental_loss\", label: \"Lost or mixed up by accident\", key: \"2\", locus: \"material_external\", def: \"Lost, sent to the wrong place, overlooked, arrives at the wrong time.\" },\n    { v: \"intentional_withholding\", label: \"Kept back on purpose\", key: \"3\", locus: \"social_institutional\", def: \"A secret kept, a letter intercepted, burned or forged, a lie, a deliberate silence.\" },\n    { v: \"misinterpretation\", label: \"Misunderstood\", key: \"4\", locus: \"social_institutional\", def: \"The message arrives but is misread, ambiguous, or someone is mistaken for someone else.\" },\n    { v: \"success_resolution\", label: \"A message solves it\", key: \"5\", locus: null, def: \"Communication works and removes the obstacle (the happy counterpart).\" },\n    { v: \"none\", label: \"None of these / unclear\", key: \"6\", locus: null, def: \"It is about information, but none of the causes above fits.\" }\n  ];\n  var byV = function (list, v) { for (var i = 0; i < list.length; i++) if (list[i].v === v) return list[i]; return null; };\n  var nameOf = function (list, v) { var o = byV(list, v); return o ? o.label : \"—\"; };\n\n  var $ = function (id) { return document.getElementById(id); };\n  var state = null;     // current label state\n  var item = null;      // current item {item_id, text, ctx_before, ctx_after}\n  var queue = null;     // current queue name\n  var queues = [];      // [{queue,title,done,total,locked}]\n  var busy = false, feedbackOn = false, paused = false;\n  var activeMs = 0, visibleSince = null;\n\n  // ---- per-browser conveniences only (never required to work)\n  function lsGet(k) { try { return JSON.parse(localStorage.getItem(k) || \"null\"); } catch (e) { return null; } }\n  function lsSet(k, v) { try { if (v === null) localStorage.removeItem(k); else localStorage.setItem(k, JSON.stringify(v)); } catch (e) { /* ignore */ } }\n  var LS = \"ald-ann:\" + BASE.split(\"/\").pop().slice(0, 10) + \":\";\n\n  function blank() { return { has_obstacle: null, domain: null, locus: null, failure_cause: null, evidence: [] }; }\n\n  // ---- timer: counts only time while the tab is visible and not on a break\n  function timerStart(ms) { activeMs = ms || 0; visibleSince = document.hidden || paused ? null : Date.now(); }\n  function timerPause() { if (visibleSince) { activeMs += Date.now() - visibleSince; visibleSince = null; } }\n  function timerResume() { if (!visibleSince && !document.hidden && !paused) visibleSince = Date.now(); }\n  function timerSeconds() { return (activeMs + (visibleSince ? Date.now() - visibleSince : 0)) / 1000; }\n  document.addEventListener(\"visibilitychange\", function () { if (document.hidden) { timerPause(); saveDraft(); } else timerResume(); });\n  window.addEventListener(\"pagehide\", saveDraft);\n\n  function saveDraft() {\n    if (!item || !state || feedbackOn) return;\n    lsSet(LS + \"draft\", { item_id: item.item_id, state: state, note: $(\"note\").value, ms: Math.round(timerSeconds() * 1000) });\n  }\n\n  // ---- option buttons\n  function makeOpts(container, list, onClick, keyPrefix) {\n    list.forEach(function (o) {\n      var b = document.createElement(\"button\");\n      b.type = \"button\"; b.className = \"opt\";\n      b.dataset.v = o.v; b.setAttribute(\"aria-pressed\", \"false\");\n      if (o.def) b.title = o.def;\n      var k = document.createElement(\"kbd\"); k.textContent = (keyPrefix || \"\") + o.key;\n      var s = document.createElement(\"span\"); s.textContent = o.label;\n      if (o.sub) { var sub = document.createElement(\"span\"); sub.className = \"sub\"; sub.textContent = o.sub; s.appendChild(sub); }\n      b.appendChild(k); b.appendChild(s);\n      b.addEventListener(\"click\", function () { onClick(o.v); b.blur(); });\n      container.appendChild(b);\n    });\n  }\n  function helpList(dl, list) {\n    list.forEach(function (o) {\n      var dt = document.createElement(\"dt\"); dt.textContent = o.key + \"  \" + o.label;\n      var dd = document.createElement(\"dd\"); dd.textContent = o.def;\n      dl.appendChild(dt); dl.appendChild(dd);\n    });\n  }\n  makeOpts($(\"hasObstacle\"), HAS, setHas);\n  makeOpts($(\"domains\"), DOMAINS, setDomain);\n  makeOpts($(\"loci\"), LOCI, setLocus);\n  makeOpts($(\"fcs\"), FCS, setFc, \"⇧\");\n  helpList($(\"helpDomains\"), DOMAINS);\n  helpList($(\"helpLoci\"), LOCI);\n  helpList($(\"helpFcs\"), FCS);\n\n  // ---- state transitions\n  function setHas(v) {\n    state.has_obstacle = v;\n    if (v !== \"yes\") { state.domain = null; state.locus = null; state.failure_cause = null; }\n    render();\n  }\n  function setDomain(v) {\n    state.domain = state.domain === v ? null : v;\n    if (state.domain) state.has_obstacle = \"yes\";\n    if (state.domain !== \"COMMUNICATION_INFORMATION\") state.failure_cause = null;\n    render();\n  }\n  function setLocus(v) {\n    state.has_obstacle = \"yes\";\n    state.locus = state.locus === v ? null : v; render();\n  }\n  function setFc(v) {\n    if (state.domain !== \"COMMUNICATION_INFORMATION\") { say(\"The cause only applies to Communication / information.\"); return; }\n    state.failure_cause = state.failure_cause === v ? null : v; render();\n  }\n\n  function press(container, pred) {\n    Array.prototype.forEach.call(container.children, function (b) { b.setAttribute(\"aria-pressed\", pred(b.dataset.v) ? \"true\" : \"false\"); });\n  }\n  function render() {\n    if (!state) return;\n    press($(\"hasObstacle\"), function (v) { return v === state.has_obstacle; });\n    press($(\"domains\"), function (v) { return v === state.domain; });\n    press($(\"loci\"), function (v) { return v === state.locus; });\n    press($(\"fcs\"), function (v) { return v === state.failure_cause; });\n    var yes = state.has_obstacle === \"yes\";\n    var other = state.has_obstacle && !yes;\n    $(\"domainSet\").classList.toggle(\"dim\", !!other);\n    $(\"locusSet\").classList.toggle(\"dim\", !!other);\n    $(\"fcSet\").classList.toggle(\"hidden\", state.domain !== \"COMMUNICATION_INFORMATION\");\n    var ev = $(\"evList\"); ev.innerHTML = \"\";\n    if (!state.evidence.length) {\n      var li0 = document.createElement(\"li\"); li0.className = \"ev-empty\"; li0.style.border = \"0\"; li0.style.background = \"none\"; li0.style.padding = \"0\";\n      li0.textContent = \"None (optional).\"; ev.appendChild(li0);\n    }\n    state.evidence.forEach(function (q, idx) {\n      var li = document.createElement(\"li\"); li.textContent = \"“\" + q + \"”\";\n      var x = document.createElement(\"button\"); x.type = \"button\"; x.textContent = \"×\"; x.title = \"Remove\";\n      x.addEventListener(\"click\", function () { state.evidence.splice(idx, 1); render(); });\n      li.appendChild(x); ev.appendChild(li);\n    });\n    renderText();\n  }\n\n  // ---- passage rendering with evidence highlights\n  function paras(el, text) {\n    el.innerHTML = \"\";\n    String(text || \"\").split(/\\n\\s*\\n/).forEach(function (p) {\n      if (!p.trim()) return;\n      var e = document.createElement(\"p\"); e.textContent = p.replace(/\\s*\\n\\s*/g, \" \").trim(); el.appendChild(e);\n    });\n  }\n  function renderText() {\n    var el = $(\"text\");\n    if (!item) return;\n    var t = item.text, ranges = [];\n    state.evidence.forEach(function (q) { var i = t.indexOf(q); if (i >= 0) ranges.push([i, i + q.length]); });\n    ranges.sort(function (a, b) { return a[0] - b[0]; });\n    var merged = [];\n    ranges.forEach(function (r) {\n      var last = merged[merged.length - 1];\n      if (last && r[0] <= last[1]) last[1] = Math.max(last[1], r[1]); else merged.push([r[0], r[1]]);\n    });\n    el.innerHTML = \"\";\n    var re = /\\n\\s*\\n/g, start = 0, m, blocks = [];\n    while ((m = re.exec(t)) !== null) { blocks.push([start, m.index]); start = m.index + m[0].length; }\n    blocks.push([start, t.length]);\n    blocks.forEach(function (bk) {\n      if (!t.slice(bk[0], bk[1]).trim()) return;\n      var p = document.createElement(\"p\"), pos = bk[0];\n      merged.forEach(function (r) {\n        var a = Math.max(r[0], bk[0]), b = Math.min(r[1], bk[1]);\n        if (a >= b) return;\n        if (a > pos) p.appendChild(document.createTextNode(t.slice(pos, a).replace(/\\s*\\n\\s*/g, \" \")));\n        var mk = document.createElement(\"mark\"); mk.textContent = t.slice(a, b).replace(/\\s*\\n\\s*/g, \" \"); p.appendChild(mk);\n        pos = b;\n      });\n      if (pos < bk[1]) p.appendChild(document.createTextNode(t.slice(pos, bk[1]).replace(/\\s*\\n\\s*/g, \" \")));\n      el.appendChild(p);\n    });\n  }\n\n  // ---- optional evidence from the current selection (keyboard e, or the button on touch screens)\n  var lastSel = \"\";\n  document.addEventListener(\"selectionchange\", function () {\n    var sel = window.getSelection();\n    if (sel && !sel.isCollapsed && sel.rangeCount) {\n      var node = sel.getRangeAt(0).commonAncestorContainer;\n      if ($(\"text\").contains(node.nodeType === 1 ? node : node.parentNode)) lastSel = sel.toString();\n    }\n  });\n  function addEvidence() {\n    var sel = window.getSelection();\n    var q = (sel && !sel.isCollapsed ? sel.toString() : lastSel).replace(/\\s+/g, \" \").trim();\n    if (!q) { say(\"Select some words in the bordered passage first.\"); return; }\n    var exact = findExact(item.text, q);\n    if (exact === null) { say(\"Evidence must come from the bordered passage; try a shorter span.\"); return; }\n    if (state.evidence.indexOf(exact) < 0) state.evidence.push(exact);\n    if (sel) sel.removeAllRanges();\n    lastSel = \"\";\n    $(\"extras\").open = true;\n    say(\"Evidence added.\", true);\n    render();\n  }\n  function findExact(text, q) {\n    if (text.indexOf(q) >= 0) return q;\n    var pat = q.split(\" \").map(function (w) { return w.replace(/[.*+?^$()|[\\]\\\\{}]/g, \"\\\\$&\"); }).join(\"\\\\s+\");\n    var m = new RegExp(pat).exec(text);\n    return m ? m[0] : null;\n  }\n\n  // ---- messages\n  var msgTimer = null;\n  function say(t, ok) {\n    var m = $(\"msg\"); m.textContent = t; m.className = ok ? \"ok\" : \"\";\n    clearTimeout(msgTimer); msgTimer = setTimeout(function () { m.textContent = \"\"; }, 4000);\n  }\n\n  // ---- network\n  function api(path, body) {\n    var opt = body === undefined ? {} : { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify(body) };\n    return fetch(BASE + path, opt).then(function (r) {\n      return r.json().catch(function () { return {}; }).then(function (j) {\n        if (!r.ok) { var e = new Error(j.error || (\"HTTP \" + r.status)); e.status = r.status; throw e; }\n        return j;\n      });\n    });\n  }\n\n  // ---- header: set tabs and progress\n  function qState(q) { for (var i = 0; i < queues.length; i++) if (queues[i].queue === q) return queues[i]; return null; }\n  function renderTabs() {\n    var tabs = $(\"tabs\"); tabs.innerHTML = \"\";\n    tabs.classList.toggle(\"hidden\", queues.length < 2);\n    queues.forEach(function (s) {\n      var b = document.createElement(\"button\");\n      b.type = \"button\"; b.className = \"tab\" + (s.locked ? \" locked\" : \"\");\n      b.setAttribute(\"aria-current\", s.queue === queue ? \"true\" : \"false\");\n      b.textContent = s.display + \" \" + s.done + \"/\" + s.total + (s.locked ? \" (locked)\" : \"\");\n      b.title = s.locked ? \"Unlocks when you finish the practice items\" : \"Switch to \" + s.display + \" (q)\";\n      b.addEventListener(\"click\", function () { switchQueue(s.queue); b.blur(); });\n      tabs.appendChild(b);\n    });\n  }\n  function setProgress(p) {\n    if (!p) return;\n    var pct = p.total ? Math.round(100 * p.done / p.total) : 0;\n    $(\"bar\").style.width = pct + \"%\";\n    var left = p.total - p.done;\n    var mins = Math.max(1, Math.round(left * SECONDS_PER_ITEM / 60));\n    $(\"count\").textContent = p.done + \" / \" + p.total + (left > 0 ? \" · ~\" + (mins >= 90 ? (Math.round(mins / 6) / 10) + \" h\" : mins + \" min\") + \" left\" : \"\");\n  }\n  function fmtMin(n) { var m = Math.max(1, Math.round(n * SECONDS_PER_ITEM / 60)); return m >= 90 ? (Math.round(m / 6) / 10) + \" hours\" : m + \" minutes\"; }\n\n  // ---- showing items and panels\n  function showPanel(html) {\n    item = null; state = null;\n    $(\"article\").classList.add(\"hidden\"); $(\"side\").classList.add(\"hidden\");\n    var p = $(\"panel\"); p.innerHTML = html; p.classList.remove(\"hidden\");\n    window.scrollTo(0, 0);\n  }\n  function showItem(j, prefill) {\n    queue = j.queue; queues = j.queues || queues;\n    lsSet(LS + \"queue\", queue);\n    renderTabs();\n    setProgress(j.progress);\n    feedbackOn = false;\n    $(\"feedback\").classList.add(\"hidden\"); $(\"form\").classList.remove(\"hidden\");\n    if (!j.item_id) { finishedPanel(); return; }\n    $(\"panel\").classList.add(\"hidden\"); $(\"article\").classList.remove(\"hidden\"); $(\"side\").classList.remove(\"hidden\");\n    item = { item_id: j.item_id, text: j.text || \"\", ctx_before: j.ctx_before || \"\", ctx_after: j.ctx_after || \"\" };\n    $(\"plabel\").textContent = queue === \"practice\" ? \"Practice \\u00b7 judge this passage (you'll see the reference after)\" :\n      (queue === \"cert\" || queue === \"retake\") ? \"Check \\u00b7 judge this passage (no feedback in this round)\" : \"Judge this passage\";\n    paras($(\"ctxBefore\"), item.ctx_before);\n    paras($(\"ctxAfter\"), item.ctx_after);\n    [\"ctxBeforeWrap\", \"ctxAfterWrap\"].forEach(function (id) { $(id).classList.remove(\"open\"); $(id).querySelector(\".ctx-toggle\").textContent = \"show all\"; });\n    $(\"ctxBeforeWrap\").classList.toggle(\"hidden\", !item.ctx_before.trim());\n    $(\"ctxAfterWrap\").classList.toggle(\"hidden\", !item.ctx_after.trim());\n    state = blank();\n    $(\"note\").value = \"\";\n    var ms = 0;\n    var draft = lsGet(LS + \"draft\");\n    if (prefill) {\n      var L = prefill.label || {};\n      state.has_obstacle = L.has_obstacle || null;\n      state.domain = Array.isArray(L.domain) ? (L.domain[0] || null) : (L.domain || null);\n      state.locus = L.locus || null;\n      state.failure_cause = L.failure_cause || null;\n      state.evidence = prefill.evidence ? prefill.evidence.split(\"\\n\").filter(Boolean) : [];\n      $(\"note\").value = L.note || \"\";\n    } else if (draft && draft.item_id === item.item_id && draft.state) {\n      state = draft.state; state.evidence = state.evidence || [];\n      $(\"note\").value = draft.note || \"\"; ms = draft.ms || 0;\n    }\n    $(\"extras\").open = !!(state.evidence.length || $(\"note\").value);\n    render();\n    window.scrollTo(0, 0);\n    timerStart(ms);\n  }\n  function finishedPanel() {\n    var next = null;\n    queues.forEach(function (s) { if (!next && !s.locked && s.done < s.total && s.queue !== queue) next = s; });\n    var cur = qState(queue);\n    if (queue === \"practice\") { practiceSummary(next); return; }\n    if (queue === \"cert\" || queue === \"retake\") { certPanel(queue); return; }\n    if (!cur) { showPanel(\"<h2>Nothing to do yet</h2><p>No passages have been assigned to this link yet. Please check back later.</p>\"); return; }\n    showPanel(\"<h2>\" + esc(cur.display) + \" finished</h2><p>All \" + cur.total + \" passages in this set are labelled. Thank you!</p>\" +\n      (next ? \"<p>You still have <b>\" + (next.total - next.done) + \"</b> passages in the \" + esc(next.display.toLowerCase()) + \".</p><button class='primary' id='goNext'>Go to \" + esc(next.display) + \" <kbd>Enter</kbd></button>\" :\n        \"<p>You can close this page. (Press u to reopen your last answer.)</p>\"));\n    if (next) $(\"goNext\").addEventListener(\"click\", function () { switchQueue(next.queue); });\n  }\n  function nameRow(l) {\n    if (l.has_obstacle !== \"yes\") return nameOf(HAS, l.has_obstacle);\n    return nameOf(DOMAINS, l.domain) + \" \\u00b7 \" + nameOf(LOCI, l.locus);\n  }\n  function certPanel(round) {\n    api(\"/cert_review?round=\" + round).then(function (j) {\n      var n = j.n, okObs = Math.round(j.obs_agree * n);\n      var head = \"<p>Obstacle yes/no matched the reference on <b>\" + okObs + \" of \" + n + \"</b>; agreement on where the resistance comes from (corrected for chance): <b>\" + j.locus_kappa.toFixed(2) + \"</b>. To pass you need at least 75% and 0.60.</p>\";\n      var html;\n      if (j.passed || j.status === \"passed\" || j.status === \"override\") {\n        var main = qState(\"audit\") || qState(\"teaching\");\n        html = \"<h2>You passed the check</h2>\" + head + \"<p>Thank you for reading carefully. The main set is now unlocked.</p>\" +\n          (main ? \"<button class='primary' id='goNext'>Start the \" + esc(main.display.toLowerCase()) + \" <kbd>Enter</kbd></button>\" : \"\");\n        showPanel(html + missList(j.misses));\n        if (main) $(\"goNext\").addEventListener(\"click\", function () { switchQueue(main.queue); });\n        return;\n      }\n      if (j.status === \"failed_retake_available\" || j.status === \"in_retake\") {\n        html = \"<h2>Not quite yet</h2>\" + head + \"<p>That is normal for a first try. Below are the passages where your answer differed from the reference, with the reasons. Read them, look again at the guide's tricky cases, then take the second check (20 new passages). There is no time limit.</p>\" +\n          \"<button class='primary' id='goNext'>Start the second check <kbd>Enter</kbd></button>\";\n        showPanel(html + missList(j.misses));\n        $(\"goNext\").addEventListener(\"click\", function () { switchQueue(\"retake\"); });\n        return;\n      }\n      showPanel(\"<h2>Thank you</h2>\" + head + \"<p>Your answers differed from the reference a bit too often for the main set this time. The study team will get in touch with you. Your work on these passages is still useful for training.</p>\" + missList(j.misses));\n    }).catch(function (e) { showPanel(\"<h2>Round finished</h2><p>(\" + esc(e.message) + \")</p>\"); });\n  }\n  function missList(m) {\n    if (!m || !m.length) return \"\";\n    return \"<h3 style='font-family:var(--sans);font-size:12px;text-transform:uppercase;letter-spacing:.07em;color:var(--red);margin-top:26px'>Where you differed (\" + m.length + \")</h3>\" +\n      m.map(function (x) {\n        return \"<div class='miss'><p class='ex'>\" + esc(x.excerpt) + \"</p><table class='cmp'><tr><th>You</th><td class='diff'>\" + esc(nameRow(x.label)) +\n          \"</td></tr><tr><th>Reference</th><td class='same'>\" + esc(nameRow(x.reference)) + \"</td></tr></table><div class='rationale'><b>Why</b>\" + esc(x.reference.rationale) + \"</div></div>\";\n      }).join(\"\");\n  }\n  function practiceSummary(next) {\n    api(\"/practice_review\").then(function (j) {\n      var n = j.items.length, h = 0, d = 0, nd = 0, l = 0;\n      j.items.forEach(function (r) {\n        if (r.label.has_obstacle === r.reference.has_obstacle) h++;\n        if (r.reference.has_obstacle === \"yes\" && r.label.has_obstacle === \"yes\") { nd++; if (r.label.domain === r.reference.domain) d++; if (r.label.locus === r.reference.locus) l++; }\n      });\n      showPanel(\"<h2>Practice finished</h2>\" +\n        \"<p>Obstacle yes/no: you matched the reference on <b>\" + h + \" of \" + n + \"</b>.</p>\" +\n        (nd ? \"<p>Where you both saw an obstacle: same kind on <b>\" + d + \" of \" + nd + \"</b>, same source on <b>\" + l + \" of \" + nd + \"</b>.</p>\" : \"\") +\n        \"<p>Experts disagree on some of these too; the point is to share the same rules. If a feedback note surprised you, have another look at the guide's tricky cases.</p>\" +\n        (next ? \"<p>The \" + esc(next.display.toLowerCase()) + \" is now unlocked: <b>\" + (next.total - next.done) + \"</b> passages, about \" + fmtMin(next.total - next.done) + \" in total. You do not need to do it in one sitting.</p><button class='primary' id='goNext'>Start the \" + esc(next.display.toLowerCase()) + \" <kbd>Enter</kbd></button>\" : \"\"));\n      if (next) $(\"goNext\").addEventListener(\"click\", function () { switchQueue(next.queue); });\n    }).catch(function (e) { showPanel(\"<h2>Practice finished</h2><p>(\" + esc(e.message) + \")</p>\"); });\n  }\n  function esc(s) { return String(s).replace(/[&<>\"']/g, function (c) { return { \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]; }); }\n\n  function loadNext(q, prefill) {\n    busy = true;\n    var path = \"/next\" + (q ? \"?queue=\" + encodeURIComponent(q) : \"\");\n    return api(path).then(function (j) { showItem(j, prefill); })\n      .catch(function (e) {\n        if (e.status === 423 || e.status === 404) return loadNext(null, prefill);\n        say(\"Could not load: \" + e.message);\n      })\n      .then(function () { busy = false; });\n  }\n  function switchQueue(q) {\n    if (busy) return;\n    var s = qState(q);\n    if (!s) return;\n    if (s.locked) { say(\"Finish the practice items first; then this set unlocks.\"); return; }\n    saveDraft();\n    loadNext(q);\n  }\n  function cycleQueue() {\n    var open = queues.filter(function (s) { return !s.locked; });\n    if (open.length < 2) return;\n    var i = 0; for (; i < open.length; i++) if (open[i].queue === queue) break;\n    switchQueue(open[(i + 1) % open.length].queue);\n  }\n\n  function submit() {\n    if (busy || !state || !item || feedbackOn) return;\n    if (!state.has_obstacle) { say(\"Answer question 1 first: yes (y), no (n) or can’t tell (c).\"); return; }\n    if (state.has_obstacle === \"yes\" && !state.domain) { say(\"Pick what kind of thing is in the way (1–9, o).\"); return; }\n    if (state.domain === \"COMMUNICATION_INFORMATION\" && !state.failure_cause) { say(\"Pick why the communication fails (Shift+1–6).\"); return; }\n    if (state.has_obstacle === \"yes\" && !state.locus) { say(\"Pick where the resistance comes from (m, s, i).\"); return; }\n    var yes = state.has_obstacle === \"yes\";\n    var label = {\n      has_obstacle: state.has_obstacle,\n      domain: yes ? state.domain : null,\n      locus: yes ? state.locus : null,\n      failure_cause: yes && state.domain === \"COMMUNICATION_INFORMATION\" ? state.failure_cause : null,\n      note: $(\"note\").value.trim()\n    };\n    busy = true;\n    api(\"/label\", {\n      item_id: item.item_id,\n      label_json: label,\n      evidence_text: state.evidence.join(\"\\n\"),\n      seconds_spent: Math.round(timerSeconds() * 10) / 10\n    }).then(function (j) {\n      busy = false;\n      lsSet(LS + \"draft\", null);\n      queues = j.queues || queues;\n      renderTabs(); setProgress(j.progress);\n      if (j.feedback) { showFeedback(label, j.feedback); return; }\n      say(\"Saved.\", true);\n      return loadNext(queue);\n    }).catch(function (e) {\n      busy = false;\n      if (e.status === 409) { say(\"Already saved.\"); return loadNext(queue); }\n      say(\"Not saved: \" + e.message + \". Check your connection and press Enter again.\");\n    });\n  }\n  function showFeedback(mine, ref) {\n    feedbackOn = true;\n    timerPause();\n    var rows = [[\"Obstacle?\", nameOf(HAS, mine.has_obstacle), nameOf(HAS, ref.has_obstacle)]];\n    if (mine.has_obstacle === \"yes\" || ref.has_obstacle === \"yes\") {\n      rows.push([\"Kind\", nameOf(DOMAINS, mine.domain), nameOf(DOMAINS, ref.domain)]);\n      if (mine.domain === \"COMMUNICATION_INFORMATION\" || ref.domain === \"COMMUNICATION_INFORMATION\")\n        rows.push([\"Why it fails\", nameOf(FCS, mine.failure_cause), nameOf(FCS, ref.failure_cause)]);\n      rows.push([\"Source\", nameOf(LOCI, mine.locus), nameOf(LOCI, ref.locus)]);\n    }\n    var body = $(\"cmpBody\"); body.innerHTML = \"\";\n    rows.forEach(function (r) {\n      var same = r[1] === r[2];\n      var tr = document.createElement(\"tr\");\n      var th = document.createElement(\"td\"); th.innerHTML = esc(r[0]) + \"<br><span class='verdict \" + (same ? \"same\" : \"diff\") + \"'>\" + (same ? \"same\" : \"different\") + \"</span>\";\n      var a = document.createElement(\"td\"); a.textContent = r[1]; a.className = same ? \"same\" : \"diff\";\n      var b = document.createElement(\"td\"); b.textContent = r[2]; b.className = same ? \"same\" : \"diff\";\n      tr.appendChild(th); tr.appendChild(a); tr.appendChild(b); body.appendChild(tr);\n    });\n    $(\"rationale\").textContent = ref.rationale || \"\";\n    $(\"form\").classList.add(\"hidden\"); $(\"feedback\").classList.remove(\"hidden\");\n    if (window.matchMedia(\"(max-width: 900px)\").matches) $(\"feedback\").scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n  }\n  function afterFeedback() { if (!busy) loadNext(queue); }\n\n  function undo() {\n    if (busy || feedbackOn) return;\n    if (queue === \"practice\" || queue === \"cert\" || queue === \"retake\") { say(\"Practice and check answers are final.\"); return; }\n    busy = true;\n    api(\"/undo\", { queue: queue }).then(function (j) {\n      busy = false;\n      if (!j.undone) { setProgress(j.progress); say(\"Nothing to undo in this set.\"); return; }\n      lsSet(LS + \"draft\", null);\n      say(\"Reopened your last submission.\", true);\n      return loadNext(queue, { label: j.previous_label, evidence: j.evidence_text });\n    }).catch(function (e) { busy = false; say(\"Undo failed: \" + e.message); });\n  }\n\n  // ---- overlays\n  function toggle(id, show) {\n    var h = $(id);\n    var on = show === undefined ? h.classList.contains(\"hidden\") : show;\n    h.classList.toggle(\"hidden\", !on);\n    return on;\n  }\n  function openBreak() {\n    saveDraft();\n    paused = true; timerPause();\n    var s = qState(queue);\n    $(\"pauseStats\").textContent = s ? \"So far in the \" + s.display.toLowerCase() + \": \" + s.done + \" of \" + s.total + \" done.\" : \"\";\n    toggle(\"pause\", true);\n  }\n  function closeBreak() { paused = false; toggle(\"pause\", false); timerResume(); }\n  function openGuide() { window.open(\"/annotate/guide\", \"_blank\", \"noopener,noreferrer\"); }\n\n  function welcome(j) {\n    var st = j.queues || [];\n    if (!st.length) return false;\n    var any = st.some(function (s) { return s.done > 0; });\n    if (any || lsGet(LS + \"welcomed\")) return false;\n    var pr = qState(\"practice\"), main = qState(\"audit\"), te = qState(\"teaching\");\n    var html = \"<p>You will read short passages (about 350 words) from novels and stories published 1800–1929 and answer three quick questions about each. Most take <b>25–35 seconds</b>.</p>\";\n    var ce = qState(\"cert\");\n    if (pr) html += \"<p><b>Start with the guide</b> (about 10 minutes). Then do <b>\" + pr.total + \" practice passages</b>: after each one you will see a reference answer and a short explanation.</p>\";\n    if (ce) html += \"<p>Next comes a <b>check</b> of \" + ce.total + \" passages without feedback (about \" + fmtMin(ce.total) + \"). It unlocks the main set when your answers mostly agree with the reference. If not, you get to review your misses and take one second check.</p>\";\n    if (main) html += \"<p>The main set has <b>\" + main.total + \"</b> passages, about \" + fmtMin(main.total) + \" in total. Work in sessions of 20–30 minutes; use <b>Break</b> at the top (key <kbd>b</kbd>) to pause. Everything you submit is saved at once, and your personal link brings you back to where you stopped.</p>\";\n    if (te) html += \"<p>You also have a separate teaching set of \" + te.total + \" passages (tab at the top).</p>\";\n    html += \"<p><b>When you are unsure, choose “Can’t tell”.</b> That is a real answer, not a failure.</p><p style='color:var(--muted)'>You will never see which book a passage comes from. Please don’t look it up.</p>\";\n    $(\"welcomeBody\").innerHTML = html;\n    toggle(\"welcome\", true);\n    return true;\n  }\n  function closeWelcome() { lsSet(LS + \"welcomed\", true); toggle(\"welcome\", false); }\n\n  $(\"helpBtn\").addEventListener(\"click\", function () { toggle(\"help\"); });\n  $(\"breakBtn\").addEventListener(\"click\", openBreak);\n  $(\"resumeBtn\").addEventListener(\"click\", closeBreak);\n  $(\"startBtn\").addEventListener(\"click\", closeWelcome);\n  [\"help\", \"welcome\"].forEach(function (id) { $(id).addEventListener(\"click\", function (e) { if (e.target === $(id)) toggle(id, false); }); });\n  $(\"submitBtn\").addEventListener(\"click\", submit);\n  $(\"undoBtn\").addEventListener(\"click\", undo);\n  $(\"nextBtn\").addEventListener(\"click\", afterFeedback);\n  Array.prototype.forEach.call(document.querySelectorAll(\".ctx-toggle\"), function (b) {\n    b.addEventListener(\"click\", function () {\n      var w = $(b.dataset.for), open = !w.classList.contains(\"open\");\n      w.classList.toggle(\"open\", open); b.textContent = open ? \"show less\" : \"show all\"; b.blur();\n    });\n  });\n  $(\"evBtn\").addEventListener(\"mousedown\", function (e) { e.preventDefault(); });\n  $(\"evBtn\").addEventListener(\"click\", function () { if (state && item) addEvidence(); });\n\n  // ---- keyboard\n  document.addEventListener(\"keydown\", function (e) {\n    var tag = (e.target && e.target.tagName) || \"\";\n    if (tag === \"TEXTAREA\" || tag === \"INPUT\") {\n      if (e.key === \"Escape\") { e.target.blur(); e.preventDefault(); }\n      else if (e.key === \"Enter\" && (e.ctrlKey || e.metaKey)) { e.preventDefault(); e.target.blur(); submit(); }\n      return;\n    }\n    if (e.ctrlKey || e.metaKey || e.altKey) return;\n    if (!$(\"welcome\").classList.contains(\"hidden\")) { if (e.key === \"Enter\" || e.key === \"Escape\") { closeWelcome(); e.preventDefault(); } return; }\n    if (paused) { if (e.key === \"Enter\" || e.key === \"b\" || e.key === \"Escape\") { closeBreak(); e.preventDefault(); } return; }\n    if (e.key === \"?\" || e.key === \"h\") { toggle(\"help\"); e.preventDefault(); return; }\n    if (!$(\"help\").classList.contains(\"hidden\")) { if (e.key === \"Escape\") toggle(\"help\", false); return; }\n    if (e.key === \"b\") { openBreak(); e.preventDefault(); return; }\n    if (e.key === \"g\") { openGuide(); e.preventDefault(); return; }\n    if (e.key === \"q\") { cycleQueue(); e.preventDefault(); return; }\n    if (e.key === \"u\") { undo(); e.preventDefault(); return; }\n    if (feedbackOn) { if (e.key === \"Enter\" || e.key === \" \") { afterFeedback(); e.preventDefault(); } return; }\n    if (!state) { if (e.key === \"Enter\" && $(\"goNext\")) { $(\"goNext\").click(); e.preventDefault(); } return; }\n    if (e.shiftKey && /^Digit[1-6]$/.test(e.code)) { setFc(FCS[+e.code.slice(5) - 1].v); e.preventDefault(); return; }\n    if (e.key === \"Enter\") { if (e.target && e.target.tagName === \"BUTTON\" && e.target.id !== \"submitBtn\") return; submit(); e.preventDefault(); return; }\n    if (e.shiftKey) return;\n    if (/^[1-9]$/.test(e.key)) { setDomain(DOMAINS[+e.key - 1].v); e.preventDefault(); return; }\n    switch (e.key) {\n      case \"y\": setHas(\"yes\"); break;\n      case \"n\": setHas(\"no\"); break;\n      case \"c\": setHas(\"insufficient_context\"); break;\n      case \"o\": setDomain(\"OTHER\"); break;\n      case \"m\": setLocus(\"material_external\"); break;\n      case \"s\": setLocus(\"social_institutional\"); break;\n      case \"i\": setLocus(\"internal_psychological\"); break;\n      case \"e\": addEvidence(); break;\n      case \"t\": $(\"extras\").open = true; $(\"note\").focus(); break;\n      default: return;\n    }\n    e.preventDefault();\n  });\n\n  // ---- start: resume the set used last time (if still open), else the server's default\n  var startQ = lsGet(LS + \"queue\");\n  busy = true;\n  api(\"/state\").then(function (st) {\n    var s = null;\n    (st.queues || []).forEach(function (x) { if (x.queue === startQ && !x.locked && x.done < x.total) s = x; });\n    return api(\"/next\" + (s ? \"?queue=\" + encodeURIComponent(s.queue) : \"\"));\n  }).then(function (j) { busy = false; showItem(j); welcome(j); })\n    .catch(function (e) { busy = false; say(\"Could not load: \" + e.message); });\n})();\n</script>\n</body>\n</html>\n";
